people_man_1 15 12 S static FLAG_HIDE_BIRTH_ISLAND_DEOXYS_TRIANGLE LOCALID_BIRTH_ISLAND_EXTERIOR_ROCK 0
pokemon_deoxys 15 3 S static FLAG_HIDE_DEOXYS LOCALID_BIRTH_ISLAND_DEOXYS 0
